const {app,BrowserWindow}=require('electron');
const fs=require('node:fs/promises'),assert=require('node:assert/strict');
const url=process.env.GOOESHELL_KEY_PUSH_UI_URL,report=process.env.GOOESHELL_KEY_PUSH_UI_REPORT;
if(!url||new URL(url).hostname!=='127.0.0.1'||!report||!process.env.GOOESHELL_KEY_PUSH_UI_DATA)throw new Error('Isolated fixture required');
app.setPath('userData',process.env.GOOESHELL_KEY_PUSH_UI_DATA);app.commandLine.appendSwitch('force-device-scale-factor','1');
let win,phase='start';const result={checks:{},errors:[]};const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const evaluate=script=>win.webContents.executeJavaScript(script);
async function until(expression,label){const end=Date.now()+7000;while(!await evaluate(expression)){if(Date.now()>end)throw new Error('Timeout: '+label);await delay(30);}}
async function click(label){const expression=`[...document.querySelectorAll('button')].find(x=>!x.disabled&&(x.textContent.trim()===${JSON.stringify(label)}||x.getAttribute('aria-label')===${JSON.stringify(label)}))`;await until(`Boolean(${expression})`,label);await evaluate(`${expression}.click()`);await delay(45);}
async function fill(selector,value){await evaluate(`(()=>{const x=document.querySelector(${JSON.stringify(selector)});x.focus();x.select();})()`);await win.webContents.insertText(value);await delay(35);}
async function picture(label){await delay(120);await fs.writeFile(report+'.'+label+'.png',(await win.webContents.capturePage()).toPNG());}
async function run(){await app.whenReady();win=new BrowserWindow({width:1050,height:900,show:false,webPreferences:{contextIsolation:true,sandbox:true,nodeIntegration:false,backgroundThrottling:false}});win.webContents.on('console-message',(...args)=>{const d=args[0],message=typeof args[2]==='string'?args[2]:d.message,level=typeof args[1]==='number'?args[1]:d.level;if(level>=3||level==='error')result.errors.push(message);});await win.loadURL(url);win.show();win.focus();win.webContents.focus();await until('Boolean(document.querySelector(".key-push-dialog"))','dialog');
 phase='prepare';assert.equal(await evaluate('[...document.querySelectorAll("button")].find(x=>x.textContent==="推送公钥").disabled'),true);await click('选择文件…');await fill('#key-passphrase-input','fixture-secret');await evaluate('window.keyPushFixture.failPrepare=true');await click('读取密钥');assert.match(await evaluate('document.querySelector(".form-error").textContent'),/无法读取/);await evaluate('window.keyPushFixture.failPrepare=false');await click('读取密钥');await until('Boolean(document.querySelector(".key-summary"))','key summary');assert.equal(await evaluate('document.querySelector("#key-passphrase-input").value'),'');assert.doesNotMatch(await evaluate('document.body.innerText'),/fixture-secret/);result.checks.readKeyAndClearPassphrase=true;
 phase='auth';await evaluate('window.keyPushFixture.response="auth"');await click('推送并验证');await until('Boolean(document.querySelector(".form-error"))','auth required');assert.equal(await evaluate('document.querySelector(".key-auth").open'),true);await fill('#key-login-secret','once-only');await fill('#key-jump-secret','jump-once');await click('推送并验证');await until('Boolean(document.querySelector(".key-push-result"))','verified');const request=await evaluate('window.keyPushFixture.pushes.at(-1)');assert.equal(request.credentials.updateSharedIdentity,false);assert.equal(request.credentials.jump.updateSharedIdentity,false);assert.equal(request.credentials.password,'once-only');assert.equal(request.credentials.jump.password,'jump-once');assert.equal(request.profile.jumpHost.host,'jump.example.test');assert.equal(await evaluate('window.keyPushFixture.applies.length'),0);result.checks.temporaryCredentialsAndExplicitApply=true;await picture('verified');await click('此连接改用密钥登录');await until('window.keyPushFixture.applied.length===1','applied');assert.equal(await evaluate('window.keyPushFixture.applied[0].loginIdentityId'),undefined);assert.deepEqual(await evaluate('window.keyPushFixture.applies'),['opaque-verification']);result.checks.verifiedSwitch=true;
 phase='public-only';await evaluate('window.keyPushFixture.reset();window.keyPushFixture.response="public"');await delay(80);await fill('#key-source-path','C:/fixture/id_ed25519.pub');await click('读取密钥');await click('推送公钥');await until('Boolean(document.querySelector(".key-push-result"))','public result');assert.match(await evaluate('document.querySelector(".key-push-result").textContent'),/已有此公钥/);assert.equal(await evaluate('[...document.querySelectorAll("button")].some(x=>x.textContent==="此连接改用密钥登录")'),false);result.checks.publicOnlyCannotSwitch=true;
 phase='generation';await click('生成新密钥');assert.equal(await evaluate('Boolean(document.querySelector(".key-summary"))'),false);assert.equal(await evaluate('Boolean(document.querySelector(".key-push-result"))'),false);await fill('#key-new-name','个人终端');await fill('#key-passphrase-input','generated-secret');await click('生成密钥');await until('Boolean(document.querySelector(".key-summary"))','generated');assert.equal(await evaluate('window.keyPushFixture.generated[0].name'),'个人终端');assert.equal(await evaluate('window.keyPushFixture.generated[0].passphrase'),'generated-secret');result.checks.changeInvalidatesVerification=true;
 phase='cancel';await evaluate('window.keyPushFixture.response="pending"');await click('推送并验证');assert.equal(await evaluate('document.querySelector("#key-new-name").disabled||document.querySelector("#key-new-name").matches(":disabled")'),true);await click('停止操作');await until('window.keyPushFixture.cancelled.length===1&&!document.querySelector("#key-new-name").matches(":disabled")','cancelled');assert.equal(await evaluate('window.keyPushFixture.applies.length'),1);assert.equal(await evaluate('Boolean(document.querySelector(".key-push-result"))'),false);result.checks.cancelLocksAndCannotApply=true;await picture('cancelled');result.success=true;
}
run().catch(error=>{result.success=false;result.phase=phase;result.error=error.stack||String(error);}).finally(async()=>{if(win&&!win.isDestroyed()&&!result.success){try{result.body=await evaluate('document.body.innerText');await picture('failure');}catch{}}await fs.writeFile(report,JSON.stringify(result,null,2));app.exit(result.success&&result.errors.length===0?0:1);});
